<script setup lang="ts">
definePageMeta({ layout: 'admin' })
const { data, pending, error, refresh } = await useFetch<any>('/api/admin/reports', { server: false, retry: false })
const maxChart = computed(() => Math.max(1, ...(data.value?.chart || []).map((item: any) => Number(item.value))))
const productRows = computed(() => data.value?.products || [])
function exportCsv() {
  const header = ['สินค้า', 'SKU', 'จำนวนที่ขาย', 'ยอดขาย', 'คงเหลือ']
  const rows = productRows.value.map((item: any) => [item.name, item.sku, item.unitsSold, item.revenue, item.stock])
  const csv = [header, ...rows].map((row) => row.map((value: any) => `"${String(value ?? '').replaceAll('"', '""')}"`).join(',')).join('\n')
  const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'anchalee-sales-report.csv'; link.click(); URL.revokeObjectURL(link.href)
}
</script>

<template>
  <div class="admin-page-wrap"><div class="admin-page-heading"><div><span class="section-kicker">YOUR BUSINESS, AT A GLANCE</span><h1>รายงานร้านค้า</h1><p>ติดตามยอดขาย สินค้ายอดนิยม และแนวโน้มคำสั่งซื้อ</p></div><button class="button button-outline" @click="exportCsv"><AppIcon name="receipt" :size="16"/> ส่งออก CSV</button></div><div v-if="pending" class="admin-loading-card"><span class="loading-spinner"/> กำลังสรุปรายงาน...</div><div v-else-if="error" class="admin-error-card"><AppIcon name="alert" :size="20"/> โหลดรายงานไม่สำเร็จ <button class="button button-outline" @click="refresh()">ลองอีกครั้ง</button></div><template v-else-if="data"><section class="stat-grid"><article class="stat-card stat-violet"><div class="stat-topline"><span>ยอดขายที่ชำระแล้ว</span><span class="stat-icon"><AppIcon name="circle-dollar" :size="19"/></span></div><div class="stat-number">฿{{ formatBaht(data.revenue) }}</div><div class="stat-foot"><span class="stat-indicator"><AppIcon name="badge-check" :size="13"/> รับชำระแล้ว</span><span>ยกเว้นรายการยกเลิก</span></div><span class="stat-orb"/></article><article class="stat-card stat-blue"><div class="stat-topline"><span>คำสั่งซื้อ</span><span class="stat-icon"><AppIcon name="bag" :size="19"/></span></div><div class="stat-number">{{ data.orders }}<small> รายการ</small></div><div class="stat-foot"><span class="stat-indicator stat-indicator-blue">ทุกสถานะ</span><span>คำสั่งซื้อที่ไม่ถูกยกเลิก</span></div><span class="stat-orb"/></article><article class="stat-card stat-peach"><div class="stat-topline"><span>ยอดเฉลี่ยต่อออเดอร์</span><span class="stat-icon"><AppIcon name="chart" :size="19"/></span></div><div class="stat-number">฿{{ formatBaht(data.averageOrder) }}</div><div class="stat-foot"><span class="stat-indicator stat-indicator-green">ภาพรวมตลอดช่วง</span><span>ยอดเฉลี่ยจากการชำระ</span></div><span class="stat-orb"/></article></section><section class="admin-panel report-chart-panel"><div class="panel-heading"><div><span class="section-kicker">PAID REVENUE</span><h2>แนวโน้มรายรับ 7 วันล่าสุด</h2></div><span class="report-chart-total">฿{{ formatBaht(data.chart.reduce((sum: number, item: any) => sum + Number(item.value), 0)) }}</span></div><div class="report-chart-legend"><span class="chart-legend-dot"/> ยอดรับชำระแล้ว</div><div class="bar-chart report-bar-chart"><div v-for="(item, index) in data.chart" :key="index" class="chart-column"><div class="chart-value" :class="{ 'chart-value-visible': item.value > 0 }">{{ item.value ? `฿${formatBaht(item.value)}` : '' }}</div><div class="chart-bar-track"><span class="chart-bar" :class="{ 'chart-bar-today': index === data.chart.length - 1 }" :style="{ height: `${Math.max(item.value ? 8 : 3, item.value / maxChart * 100)}%` }"/></div><span class="chart-day">{{ item.label }}</span></div></div><p class="report-chart-caption"><AppIcon name="alert" :size="14"/> ยอดขายในกราฟจะปรากฏเมื่อมีคำสั่งซื้อที่ได้รับการชำระเงิน</p></section><section class="admin-panel report-products-panel"><div class="panel-heading"><div><span class="section-kicker">PRODUCT PERFORMANCE</span><h2>ยอดขายแยกตามสินค้า</h2></div><NuxtLink class="panel-action" to="/admin/products">จัดการสินค้า <AppIcon name="arrow-right" :size="14"/></NuxtLink></div><div v-if="productRows.length" class="table-scroll"><table class="admin-table"><thead><tr><th>สินค้า</th><th>ขายได้</th><th>รายรับ</th><th>คงเหลือ</th><th>สัดส่วนยอดขาย</th></tr></thead><tbody><tr v-for="product in productRows" :key="product.id"><td><div class="report-product-name"><strong>{{ product.name }}</strong><small>{{ product.sku }}</small></div></td><td><strong>{{ product.unitsSold }} <small>ชิ้น</small></strong></td><td><strong>฿{{ formatBaht(product.revenue) }}</strong></td><td><span class="stock-cell" :class="{ 'stock-cell-low': product.stock <= 5 }"><i/>{{ product.stock }} ชิ้น</span></td><td><div class="sales-share"><span><i :style="{ width: `${Math.min(100, data.revenue ? product.revenue / data.revenue * 100 : 0)}%` }"/></span><small>{{ data.revenue ? Math.round(product.revenue / data.revenue * 100) : 0 }}%</small></div></td></tr></tbody></table></div><div v-else class="panel-empty"><AppIcon name="chart" :size="24"/><span>ยังไม่มีข้อมูลยอดขายสินค้า</span></div><div class="report-footnote"><AppIcon name="shield" :size="14"/> รายงานอัปเดตจากข้อมูลคำสั่งซื้อในระบบ</div></section></template></div>
</template>
